const { writeFileSync } = await import('node:fs');
const html = process.env.HTML_INPUT;
if (!html) throw new Error('Missing HTML input');
const path = '/tmp/input.html';
writeFileSync(path, html);
globalThis.htmlPath = path;

const puppeteerMod = await import('puppeteer');
const puppeteer = puppeteerMod.default || puppeteerMod;
const { createRequire } = await import('node:module');
const require = createRequire(import.meta.url);
const html3pdfPath = require.resolve('html3pdf/dist/html3pdf.bundle.min.js');
const browser = await puppeteer.launch();
const page = await browser.newPage();
await page.goto('file://' + globalThis.htmlPath);
await page.addScriptTag({ path: html3pdfPath });
const base64 = await page.evaluate(() => {
  return new Promise((resolve, reject) => {
    const element = document.body;
    // html2pdf is attached to window by the bundle
    window.html2pdf().from(element).outputPdf('datauristring')
      .then(data => {
        const parts = data.split(',');
        resolve(parts[1] || '');
      })
      .catch(reject);
  });
});
await browser.close();
globalThis.pdfBase64 = base64;
